CREATE TABLE community_answer_commands(actor_id BIGINT NOT NULL, command_key UUID NOT NULL, request_hash VARCHAR(64) NOT NULL, answer_id BIGINT NOT NULL REFERENCES community_answers(id), event_id UUID NOT NULL, PRIMARY KEY(actor_id,command_key));
CREATE TABLE community_outbox(event_id UUID PRIMARY KEY, question_id BIGINT NOT NULL REFERENCES community_questions(id), aggregate_sequence BIGINT NOT NULL, payload TEXT NOT NULL, status VARCHAR(10) NOT NULL CHECK(status IN ('PENDING','SENT','FAILED')), attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, lease_until TIMESTAMPTZ, lease_token UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, last_error VARCHAR(100), UNIQUE(question_id,aggregate_sequence));
CREATE INDEX community_outbox_due ON community_outbox(status,next_attempt_at);
